function collect(){
  var r = document.querySelector("input[name=provider]:checked");
  var custom = (el("modelCustom").value || "").trim();
  var chosen = (el("modelSelect").value || "").trim();
  var key = (el("apiKey").value || "").trim();
  var body = {
    provider: r ? r.value : undefined,
    model: custom || chosen,
    modelPro: (el("modelPro").value || "").trim(),
    ollamaBaseUrl: (el("ollamaUrl").value || "").trim(),
    botName: (el("botName").value || "").trim(),
    language: el("lang").value
  };
  if(key && state.status && state.status.providers){
    for(var pi=0; pi<state.status.providers.length; pi++){
      var pv = state.status.providers[pi];
      if(pv.id === body.provider && pv.keyEnv){ body.apiKeys = {}; body.apiKeys[pv.keyEnv] = key; }
    }
  }
  if(el("autoApprove")){ body.autoApproveTools = !!el("autoApprove").checked; }
  if(el("workspaceDir")){ body.workspaceDir = (el("workspaceDir").value || "").trim(); }
  if(el("accessCode")){ body.accessCode = (el("accessCode").value || "").trim(); }
  return body;
}
